def build_reason_ai_page(page, section, sh, eyebrow, button, a):
    def label(text):
        return '<p class="rai-kicker">'+text+'</p>'
    def heading(en, text, desc=''):
        return '<div class="rai-section-heading">'+label(en)+'<h2>'+text+'</h2>'+('<p>'+desc+'</p>' if desc else '')+'</div>'
    consult=button('/inquiry/general/','45分の適合診断について相談する','rai-primary')
    hero='''<div class="wrap"><nav class="breadcrumbs" aria-label="パンくず"><a href="/">HOME</a><span>/</span><a href="/branding/">ブランディング</a><span>/</span><span>選ばれる理由AI</span></nav></div>
<section class="rai-hero"><div class="wrap"><div class="rai-hero-grid"><div class="rai-hero-copy">
<img class="rai-logo" src="/assets/reason-ai-logo.png" width="1261" height="291" alt="選ばれる理由AI">
<p class="rai-kicker">言葉をつくる、8週間のブランディングプログラム</p>
<h1>御社が選ばれる理由を、<br><span>8週間で「言葉」に。</span></h1>
<p class="rai-hero-lead">「安いから」ではなく、<br>「御社だから」と言われるために。</p>
<p class="rai-intro">社内では当たり前の強みを、お客様が選ぶ理由へ。<br class="rai-desktop-break">AIとの対話と専門家の確認を重ね、営業・Web・採用で使える言葉として残します。</p>
<div class="actions">'''+consult+'''<a class="rai-secondary" href="#deliverables">8週間後に残るものを見る <span aria-hidden="true">↓</span></a></div>
</div><div class="rai-hero-proof"><div class="rai-proof-top"><span>FROM YOUR COMPANY</span><span>TO YOUR CUSTOMER</span></div>
<p class="rai-proof-question">「うちの強みは、品質と対応力です。」</p><p class="rai-proof-note">その言葉を、もう一歩具体的に。</p>
<div class="rai-word-stack"><div><span>01 / 提供価値</span><strong>御社は、何ができるのか。</strong></div><div><span>02 / 体験価値</span><strong>だから、お客様は<br>どう感じられるのか。</strong></div><div><span>03 / 根拠</span><strong>なぜ、そう言えるのか。</strong></div></div>
<p class="rai-proof-bottom">この3つをつなぎ、<br><strong>御社にしか言えない説明へ。</strong></p></div></div>
<div class="rai-facts"><div><strong>8<span>週間</span></strong><p>言葉をつくり、使える形に</p></div><div><strong>5<span>回</span></strong><p>コンサルタントとのオンライン面談</p></div><div><strong>1–2<span>時間 / 週</span></strong><p>ブラウザで進める取り組みの目安</p></div></div><p class="rai-small rai-time-note">キックオフは別途3時間。日々の問いへの回答や、下書きの確認を通じて進めます。</p>
</div></section>'''
    issues=['見積りになると、価格だけで比べられる。','営業担当によって、会社の説明が違う。','Webの文章が、他社と入れ替えても通じる。','強みを聞かれると「品質」「対応力」で止まる。','長く選ばれている理由を、お客様に聞けていない。','新人や求職者に、自社の違いを説明しにくい。']
    challenge=section('<div class="rai-challenge-grid"><div>'+heading('THE STARTING POINT','良い会社なのに、<br>違いが伝わらない。','言葉の材料は、すでに御社の中にあります。<br>こんな課題が、取り組みの出発点です。')+'</div><ul class="rai-issue-list">'+''.join('<li>'+x+'</li>' for x in issues)+'</ul></div>','rai-section')
    output_rows=[('営業','営業トーク台本・価格説明','「御社だから」と選ぶ理由と、「なぜこの価格なのか」を説明する言葉。','商談で使う言葉を、社内でそろえる。'),('発信','Web・採用・見積の言葉','完成した脚本を、Web原稿や採用、見積など、お客様と接する場面に合わせて整えます。','どの接点でも、同じ「選ばれる理由」を。'),('共有','接点マップ・社内共有用1枚','どこで、誰に、何を伝えるかを整理し、社内でも共有できる形にまとめます。','説明の軸を、担当者だけのものにしない。'),('運用','月次運用の型','完成した脚本を日々の営業や発信に活かすために、運用の型もお渡しします。','言葉をつくった後の、実行につなぐ。')]
    deliverables=section(heading('WHAT YOU TAKE AWAY','8週間で、御社に残るもの。','完成した「選ばれる理由の脚本」と、実際の場面で使う「活用パッケージ」。<br>8週間の終わりにダウンロードし、御社の資産として活用できます。')+'''<div class="rai-deliverables"><article class="rai-sheet"><span class="rai-number">01 / 完成した脚本</span><h3>提供価値シート</h3><p class="rai-sheet-meta">全列を含むExcel形式・根拠タグつき</p><p class="rai-sheet-count"><strong>30</strong>組を目標に、まず広く出す。</p><div class="rai-sentence"><p><span>提供価値</span>御社は、<b>＿＿＿</b>できる。</p><p><span>体験価値</span>だから、お客様は<br><b>＿＿＿</b>と感じられる。</p><p><span>根拠</span>なぜなら、<b>＿＿＿</b>。</p></div><div class="rai-evidence"><span>事実</span><span>要確認</span><span>仮説</span></div><p>広く出した言葉から、本当に強いものを見極めて絞り込みます。残る数は会社によって異なります。数をそろえるより、「比べられても、これで選ばれる」と言い切れる言葉へ。</p><p>根拠に加え、削った行とその理由、競合比較、お客様の声の分類、未回収の宿題まで残します。</p><p class="rai-output-benefit">ベレネッツとの面談で一つずつ確定した、<br>御社の「選ばれる理由」の原本です。</p></article><div class="rai-package"><p class="rai-kicker">02 / 活用パッケージ</p><h3>選ばれる理由のまとめ一式</h3><p>脚本を、実際に使う場面の形に。<br>そのまま現場で使える言葉と運用の型をまとめます。</p><div class="rai-output-list">'''+''.join('<article><span class="rai-number">'+n+'</span><div><h3>'+t+'</h3><p>'+d+'</p><strong>'+benefit+'</strong></div></article>' for n,t,d,benefit in output_rows)+'</div></div></div>','rai-section rai-soft',id='deliverables')
    screen=section(heading('INSIDE THE PROGRAM','進み方も、見つかった価値も。<br>ひとつの画面で見える。','適合診断で見えた「選ばれる理由の芽」を、アプリ上で共有。<br>現在のフェーズ、これからのステップ、質問の窓口を確認しながら進めます。')+'''<figure class="rai-screen"><div class="rai-screen-bar"><span>選ばれる理由AI / 適合診断の結果</span><span>画面例</span></div><a href="/assets/reason-ai-diagnosis-screen-20261021.png" target="_blank" rel="noopener" aria-label="適合診断の画面例を拡大して見る（別タブ）"><img src="/assets/reason-ai-diagnosis-screen-20261021.png" width="1211" height="946" alt="適合診断の画面例。左に現在のフェーズとステップ、右に発見した価値の芽や8週間の目標を表示しています。" loading="lazy"></a><figcaption>テスト企業の画面例です。診断内容・数値・日程は個別の例であり、成果を保証するものではありません。画像を選ぶと拡大できます。</figcaption></figure>
<div class="rai-screen-notes"><div><span>01</span><h3>現在地がわかる</h3><p>今のフェーズと、次に取り組むステップを確認。</p></div><div><span>02</span><h3>言葉の変化が残る</h3><p>最初の一言と、8週間後の一言を比較できます。</p></div><div><span>03</span><h3>質問を置いておける</h3><p>面談を待たずに質問を残し、同じ画面で回答を確認。</p></div></div>''','rai-section',id='screen')
    steps=[('STEP 0','キックオフ','会社を知る','3時間のキックオフで、会社の現状や材料を共有します。'),('STEP 1–2','1〜2週目','骨格をつくる','提供価値と体験価値を対に。偏りや曖昧な表現を見直し、言葉の骨格を整理。'),('STEP 3–6','3〜5週目','根拠を重ねる','お客様の「4つの不」を整理し、「なぜなら」を加える。独自の評価方法で言葉を点検。'),('STEP 7','6〜8週目','証拠で仕上げる','お客様の声・数字・第三者評価を集め、仮説を事実で裏づけます。'),('FINAL','接点への展開','使う言葉にする','営業トーク、価格説明、Web、採用へ。用途ごとに使える言葉と、運用の型に整えます。')]
    flow=section(heading('YOUR 8-WEEK JOURNEY','問いに答え、確かめ、<br>自社の言葉にしていく。','ブラウザでの取り組みと、5回のオンライン面談を組み合わせます。')+'<ol class="rai-timeline">'+''.join('<li><span class="rai-step-code">'+code+'</span><p class="rai-step-period">'+period+'</p><h3>'+title+'</h3><p>'+text+'</p></li>' for code,period,title,text in steps)+'</ol><p class="rai-flow-note">面談は、キックオフ・確認セッション3回・中間チェックの計5回。節目ごとに方向性を確認し、質問にはその都度お答えします。</p>','rai-section rai-dark',id='journey')
    roles=[('YOUR TEAM','御社が、決める。','自社の事実と判断を、言葉の中心に。',['会社資料とWebサイトを登録する','日々の問いに答え、経験を言葉にする','下書きを修正・承認・保留する']),('YOUR AI','AIが、下書きする。','白紙から考える負担を軽く。',['資料から提供価値の下書きをつくる','曖昧な言葉や偏りを見つけ、言い直しを提案','根拠となる材料を資料から拾う']),('WELLENETZ','専門家が、見極める。','「これで行ける」を、一緒に確認。',['5回の面談で、言葉と方向性を確認する','進み具合を見て、止まる前に声をかける','面談の間に届いた質問にも回答する'])]
    session_support='''<div class="rai-session-support"><div class="rai-session-copy"><p class="rai-kicker">AIとの対話 × 担当者とのオンラインセッション</p><h3>一人で迷わない。<br>節目ごとに、担当者と確かめる。</h3><p>AIとのセッションの途中には、実際のベレネッツ担当者とのオンラインセッションが組み込まれています。AIと整理した言葉を一緒に見直し、疑問や迷いを解消してから、次のステップへ進みます。</p><p>キックオフに加え、確認セッション3回と中間チェックを実施。御社の状況や考えを直接伺いながら方向性を確認することで、8週間の取り組みを着実に進められるよう支えます。</p><ul class="rai-session-points"><li><strong>言葉を、一緒に見直す</strong><span>自社の強みやお客様にとっての価値が、具体的に伝わるかを確認します。</span></li><li><strong>迷いや疑問を、そのままにしない</strong><span>AIとの対話で判断に迷った点を、担当者に直接相談できます。</span></li><li><strong>次に取り組むことを、明確にする</strong><span>進み具合と課題を共有し、次のステップで確かめることを整理します。</span></li></ul></div><figure class="rai-session-screen"><a href="/assets/reason-ai-session-flow.png" target="_blank" rel="noopener" aria-label="オンライン面談を含む進行画面を拡大する（別タブ）"><img src="/assets/reason-ai-session-flow.png" alt="AIとの各ステップの間に、キックオフ、確認セッション1、中間チェック、確認セッション2・3のオンライン面談が入る進行画面" loading="lazy"></a><figcaption>実際の進行画面の例。<br>「面談」の節目で担当者と確認します。<br>画像を選ぶと拡大できます。</figcaption></figure></div>'''
    support=section(heading('AI × YOUR TEAM × CONSULTANT','AIが下書き。御社が判断。<br>専門家が、最後まで支える。','25年以上・750社超の企業ブランディングで培ったノウハウを、<br>プログラムの進め方と問いに組み込んでいます。')+session_support+'<div class="rai-roles">'+''.join('<article>'+label(en)+'<h3>'+title+'</h3><p>'+desc+'</p><ul>'+''.join('<li>'+x+'</li>' for x in items)+'</ul></article>' for en,title,desc,items in roles)+'</div><div class="rai-support-note"><strong>自分たちで考え、選んだ言葉だから。</strong><p>完成した言葉を社内で説明し、日々の営業や発信に使っていく。そのために、御社自身の判断を大切にします。</p></div>','rai-section',id='support')
    fit=section(heading('WHO IT IS FOR','すでにある強みを、<br>伝わる言葉にしたい会社へ。')+'''<div class="rai-fit-grid"><div><h3>こんな会社に向いています</h3><ul><li>すでに選んでくれているお客様がいる。</li><li>競合との差が実際にあるのに、うまく言えていない。</li><li>経営者・事業責任者が、自分の言葉で決める意思がある。</li><li>8週間、週に1〜2時間の取り組み時間を確保できる。</li></ul><p class="rai-small">規模の目安は従業員10〜300名程度。製造・設備・建設・物流・専門サービス・BtoB販売代理などを想定しています。</p></div><div><h3>取り組む前に、確認したいこと</h3><p>まだ商品やお客様がいない場合は、言葉の材料を集めることが先です。</p><p>キャッチコピーだけの制作や、すべてを外注する進め方を求める場合は、このプログラムとは目的が異なります。</p><p>適合診断でお話を伺い、今取り組むべきことから一緒に確認します。</p></div></div><div class="rai-use-cases"><span>Web刷新の前に</span><span>営業資料の作り直しに</span><span>事業承継の節目に</span><span>採用強化の前に</span></div>''','rai-section rai-soft')
    faqs=[('AIを使い慣れていなくても進められますか？','ブラウザ上で問いに答え、下書きを確認する形で進めます。ゼロから文章を書き上げる必要はありません。進行中の質問にもベレネッツがお答えします。'),('どのくらいの時間が必要ですか？','8週間、週に1〜2時間が取り組みの目安です。キックオフは3時間で、オンライン面談は計5回。具体的な日程や進め方は、適合診断でご相談ください。'),('Webサイトや営業資料の完成品も含まれますか？','完成した提供価値シートと、営業トーク台本・価格説明・Web原稿・採用の言葉・社内共有用1枚・月次運用の型などの活用パッケージをお渡しします。Webサイトの構築やデザイン制作をご希望の場合は、別途ご相談ください。'),('適合診断では、何をしますか？','オンラインで45分、ベレネッツ代表がお話を伺い、プログラムが御社に合うかを確認します。適合する場合は、面談で見えた価値の芽をまとめた診断結果をアプリ上でお渡しします。合わない場合は、その理由と先に取り組むべきことをお伝えします。')]
    faqs.append(('ChatGPTなどの契約は必要ですか？','御社でChatGPTやClaudeなどを別途契約する必要はありません。8週間の成果物はダウンロードして自社で活用できます。その後、御社専用のブランディング・マーケティングAIを使い続ける場合は、ベレネッツとの別途継続契約が必要です。'))
    faq=section('<div class="rai-faq-grid">'+heading('QUESTIONS','始める前に、<br>知っておきたいこと。')+'<div>'+''.join('<details><summary>'+q+'</summary><p>'+answer+'</p></details>' for q,answer in faqs)+'</div></div>','rai-section')
    continuation=section(heading('BEYOND THE 8 WEEKS','8週間でつくった脚本を、<br>御社の毎日で活かす。','完成した脚本と活用パッケージは、すべて御社のもの。<br>その先の活かし方は、御社の体制に合わせて選べます。')+'''<div class="rai-after-options"><article><p class="rai-kicker">OPTION A / 自社で活用</p><h3>完成した脚本を、<br>自社の力で使う。</h3><p class="rai-option-label">継続契約は不要</p><p>ダウンロードした成果物をもとに、御社のペースで営業・発信や社内への浸透を進められます。</p></article><article class="rai-after-option-ai"><p class="rai-kicker">OPTION B / 御社専用AIで活用</p><h3>御社の脚本に沿うAIを、<br>日々の実行のパートナーに。</h3><p class="rai-option-label">ベレネッツとの別途継続契約</p><p>完成した脚本を反映した御社専用AIで、ブランディング・マーケティングに使う言葉を継続してつくれます。</p></article></div><div class="rai-dedicated-ai"><div class="rai-ai-heading"><p class="rai-kicker">YOUR BRANDING &amp; MARKETING AI</p><h3>【オプション】御社の「選ばれる理由」を知る、<br>専用AIが使える。</h3><p>ベレネッツが25年以上・750社超の支援で培ったノウハウと成功パターンに、8週間で完成した御社の脚本を組み合わせます。社内の誰が使っても、御社の価値・強み・伝えるべき物語に沿った言葉をつくれます。</p></div><div class="rai-ai-foundation"><span>ベレネッツの<br><strong>ノウハウ・成功パターン</strong></span><b aria-hidden="true">＋</b><span>8週間で完成した<br><strong>御社の「選ばれる理由」</strong></span></div><div class="rai-ai-uses"><p>御社の脚本を、さまざまな接点の言葉へ。</p><ul><li>営業トーク・提案書</li><li>価格・見積の説明</li><li>Webサイト・LPの文章</li><li>広告・チラシ・パンフレット</li><li>メルマガ・プレスリリース</li><li>動画シナリオ・SNS発信</li><li>採用・社内浸透の言葉</li><li>新商品・新サービスの打ち出し方</li></ul></div><div class="rai-ai-benefits"><article><span>01 / 別途のAI契約は不要</span><h4>ブラウザを開けば、<br>そのまま使える。</h4><p>ChatGPTやClaudeなどを御社で別途契約する必要はありません。専用AIを、ブラウザから利用できます。</p></article><article><span>02 / 御社の脚本を共有</span><h4>使う人が変わっても、<br>伝える軸がそろう。</h4><p>御社の脚本を踏まえた言葉が出てくるので、営業・広報・採用などの発信を、同じ軸で進められます。</p></article><article><span>03 / 継続して育てる</span><h4>知見も、脚本も。<br>使いながら更新する。</h4><p>ベレネッツが蓄積する知見や成功パターンをAIに反映。御社の脚本も、顧問の面談を通じて更新していきます。</p></article></div><p class="rai-ai-terms">御社専用AIの継続利用には、ベレネッツとの別途継続契約が必要です。8週間で完成した成果物は、継続契約の有無にかかわらず御社で活用できます。</p></div>''','rai-section rai-soft',id='dedicated-ai')
    cta=section('''<div class="rai-consult-grid"><div><p class="rai-kicker">START WITH A CONVERSATION</p><h2>まずは45分。<br>御社の「選ばれる理由」の<br>芽を、一緒に探しましょう。</h2><p>今の課題と、すでに持っている強みをお聞かせください。<br>この8週間が御社に合うか、適合診断で確かめます。</p></div><div>'''+consult+'''<p class="rai-small">オンラインで実施します。お問い合わせ内容に<br>「選ばれる理由AIの適合診断」とご記入ください。</p></div></div>''','rai-section rai-consult',id='consultation')
    page('/branding/reason-ai/','選ばれる理由AI', '<div class="rai-page">'+hero+challenge+deliverables+screen+flow+support+fit+faq+continuation+cta+'</div>',en='REASON AI',lead='御社が選ばれる理由を8週間で言葉に。AIとの対話と5回の専門家面談で、完成した脚本と、営業・Web・採用に使える活用パッケージが残るブランディングプログラム。',group='services',hero=False,cta=False)
